('e129f667-0510-4f07-9847-edb58356dc74',1,'quiz:7d986889','Beginner course','You drove into a quiz','quiz','[{"id":"d20efac1","question":"Which part of a car do you press to slow down or stop the vehicle?","answers":["Accelerator","Brake pedal","Clutch","Handbrake lever"],"correct":"Brake pedal"},{"id":"758d2ad7","question":"Before getting into the driver''s seat, which check should you perform first?","answers":["Adjust the rear-view mirror","Walk around the vehicle to check tyres, lights, and for any obstructions","Start the engine","Fasten the seatbelt"],"correct":"Walk around the vehicle to check tyres, lights, and for any obstructions"},{"id":"0404b32a","question":"After sitting in the driver''s seat but before starting the engine, what should you check first?","answers":["Fuel price at the nearest station","Seat position, mirrors, and seatbelt","Music/infotainment settings","Boot space"],"correct":"Seat position, mirrors, and seatbelt"}]'::jsonb),
