('e129f667-0510-4f07-9847-edb58356dc74',7,'quiz:ee625cb6','Beginner course','test your know-how','quiz','[{"id":"c2cd499e","question":"What is the correct safety practice for vehicles approaching a railway level crossing?","answers":["Park as close to the barrier/gate as possible to save time","Stop at a safe distance before the marked stop line and never queue on the tracks","Only heavy vehicles need to maintain a safe distance","Distance rules only apply if there is no gate present"],"correct":"Stop at a safe distance before the marked stop line and never queue on the tracks"},{"id":"f559a919","question":"What is a \"road junction\"?","answers":["A section of road with no traffic","A point where two or more roads meet or cross","A road with a single continuous lane","A dead-end street"],"correct":"A point where two or more roads meet or cross"},{"id":"b7e8873e","question":"In a \"T junction,\" how many roads typically meet?","answers":["Two roads meeting end to end (a straight road)","Three roads meeting to form a \"T\" shape","Four roads crossing at one point","Five or more roads"],"correct":"Three roads meeting to form a \"T\" shape"},{"id":"f85f44c6","question":"What makes a junction \"controlled\"?","answers":["It has no signs or signals at all","Traffic movement is regulated by signals, signs, or a traffic police officer","Only pedestrians can use it","It is closed to vehicles during the day"],"correct":"Traffic movement is regulated by signals, signs, or a traffic police officer"},{"id":"202e1967","question":"At an uncontrolled junction with no signs or signals, what is the general rule?","answers":["The fastest vehicle gets priority","Drivers must slow down, observe carefully, and generally give way to traffic on the right (as per local rules)","Only two-wheelers must stop","Vehicles from the left always have priority regardless of local rule"],"correct":"Drivers must slow down, observe carefully, and generally give way to traffic on the right (as per local rules)"}]'::jsonb),
('e129f667-0510-4f07-9847-edb58356dc74',8,'video:1ad66aad','Beginner course','Headlights & High Beams','video','[]'::jsonb),
('e129f667-0510-4f07-9847-edb58356dc74',8,'quiz:fca1c9ac','Beginner course','twilight trivia time','quiz','[{"id":"a706a3a2","question":"When a driver extends their right arm straight out horizontally to the side, what are they signaling?","answers":["Slowing down","Intention to turn right","Intention to turn left","Stopping completely"],"correct":"Intention to turn right"},{"id":"982825f1","question":"When a traffic constable stands facing you with one arm raised straight up vertically, what does this signal mean?","answers":["Proceed straight ahead","You may turn left freely","Stop — all traffic from every direction must halt","Speed up to clear the intersection"],"correct":"Stop — all traffic from every direction must halt"},{"id":"bb69c738","question":"What must a driver do when approaching a zebra crossing with pedestrians waiting to cross?","answers":["Speed up to cross before them","Slow down and stop to give way to pedestrians on the crossing","Sound the horn to make them wait","Only stop if a policeman is present"],"correct":"Slow down and stop to give way to pedestrians on the crossing"},{"id":"df5e382b","question":"What does \"anticipation\" mean in the context of safe driving?","answers":["Driving as fast as possible to reach the destination early","Reading the road ahead and predicting the actions of other road users before they happen","Waiting for other drivers to signal before you react","Only reacting after something happens"],"correct":"Reading the road ahead and predicting the actions of other road users before they happen"},{"id":"7baf973a","question":"What should a driver do when approaching a bus stop where a bus is pulling in (ingress)?","answers":["Overtake the bus quickly before it stops","Slow down and be prepared to stop, watching for pedestrians crossing toward the bus","Sound the horn continuously","Maintain normal speed since buses always stop close to the curb"],"correct":"Slow down and be prepared to stop, watching for pedestrians crossing toward the bus"},{"id":"08f583dc","question":"When a bus is leaving a bus stop (egress) and signaling to merge back into traffic, what should following drivers do?","answers":["Speed up to pass before the bus merges","Slow down and allow the bus to merge safely into the traffic flow","Ignore the bus''s indicator","Overtake on the left side only"],"correct":"Slow down and allow the bus to merge safely into the traffic flow"},{"id":"61d4a8ec","question":"What is the correct general method for driving near a designated bus stop area?","answers":["Park in the bus bay if it looks empty","Keep the bus bay clear, slow down, and watch for pedestrians boarding or alighting","Use the bus bay as an overtaking lane","Treat it the same as any regular stretch of road with no extra caution"],"correct":"Keep the bus bay clear, slow down, and watch for pedestrians boarding or alighting"},{"id":"75fd0ee3","question":"When you notice a visually or hearing-impaired pedestrian near the road, what should a driver do?","answers":["Proceed at normal speed since they''ll hear the vehicle","Slow down significantly and give extra space, since they may not sense the vehicle''s approach","Honk loudly to alert them","Only be cautious if a caregiver is visible"],"correct":"Slow down significantly and give extra space, since they may not sense the vehicle''s approach"},{"id":"9b00e2db","question":"Why should drivers exercise extra caution around elderly pedestrians or women accompanying small children?","answers":["They always have the legal right of way regardless of situation","They may move slower or less predictably, needing more time and space to cross safely","It''s only a courtesy, not a safety concern","No special caution is needed if they are on the footpath"],"correct":"They may move slower or less predictably, needing more time and space to cross safely"},{"id":"c30d038d","question":"How should a driver behave when approaching a slow-moving vehicle (e.g. a cart or tractor) ahead?","answers":["Tailgate closely to pressure it to move faster","Reduce speed, keep a safe following distance, and overtake only when it''s safe and legal to do so","Overtake immediately regardless of oncoming traffic","Flash headlights repeatedly instead of slowing down"],"correct":"Reduce speed, keep a safe following distance, and overtake only when it''s safe and legal to do so"},{"id":"ddd265f4","question":"Why do two-wheelers require extra attention from car/truck drivers, especially when changing lanes?","answers":["They are always faster than cars","They are smaller, can be in blind spots, and are more vulnerable in a collision","They aren''t allowed to share the road with cars","They always have right of way over all other vehicles"],"correct":"They are smaller, can be in blind spots, and are more vulnerable in a collision"},{"id":"5a321e25","question":"What driving consideration is important around autos and tempos, which often make sudden stops or turns?","answers":["Assume they will always signal well in advance","Maintain extra following distance and anticipate sudden stops or turns","Overtake them at every opportunity without checking mirrors","Treat them exactly like heavy trucks in terms of stopping distance"],"correct":"Maintain extra following distance and anticipate sudden stops or turns"},{"id":"ba190792","question":"Why is it important to keep extra distance behind large buses and trucks?","answers":["They have better brakes than cars, so a short distance is fine","They block your view ahead and take longer to stop, so more distance and visibility are needed","It''s only relevant on highways, not city roads","It''s purely a legal formality with no safety benefit"],"correct":"They block your view ahead and take longer to stop, so more distance and visibility are needed"},{"id":"d521697d","question":"What should a driver do when they hear or see an ambulance or fire engine approaching with its siren/lights on?","answers":["Maintain the current lane and speed","Safely move aside and give way as quickly as possible to let it pass","Speed up to clear the intersection before it arrives","Only give way if it is directly behind you"],"correct":"Safely move aside and give way as quickly as possible to let it pass"},{"id":"1e2412c4","question":"What is the safest way to handle an animal (e.g. a stray cow or dog) suddenly on the road ahead?","answers":["Swerve sharply without checking surroundings","Slow down well in advance and pass carefully, avoiding sudden braking or swerving that could cause a collision","Sound the horn loudly and continue at the same speed","Speed up to pass before the animal reacts"],"correct":"Slow down well in advance and pass carefully, avoiding sudden braking or swerving that could cause a collision"}]'::jsonb),
