('e129f667-0510-4f07-9847-edb58356dc74',9,'quiz:fb18aba9','Beginner course','flyover flow facts','quiz','[{"id":"038a73b6","question":"What is the main purpose of a traffic island or roundabout at a junction?","answers":["To provide extra parking space","To organize and separate traffic flows, guiding vehicles safely around the junction","To display advertisements","To increase vehicle speed through the junction"],"correct":"To organize and separate traffic flows, guiding vehicles safely around the junction"},{"id":"03a0204d","question":"What is the function of a road median?","answers":["To provide extra lanes for overtaking","To physically separate opposing traffic flows, improving safety","To mark the end of a road","To indicate a school zone"],"correct":"To physically separate opposing traffic flows, improving safety"},{"id":"fd3e3963","question":"What is the primary purpose of a bypass road?","answers":["To connect two parking lots","To route through-traffic around a congested town/city area instead of through it","To provide a pedestrian-only path","To slow down highway traffic intentionally"],"correct":"To route through-traffic around a congested town/city area instead of through it"},{"id":"b760dec9","question":"How does a \"Y junction\" typically differ from a T junction?","answers":["It has four arms instead of three","Roads meet at an angle (not a right angle), forming a \"Y\" shape","It only occurs on highways","There is no need to give way at a Y junction"],"correct":"Roads meet at an angle (not a right angle), forming a \"Y\" shape"},{"id":"85cef653","question":"A \"4-arm junction\" refers to a junction where:","answers":["Only two roads cross","Four roads meet at a single point, typically forming a crossroads","There is a roundabout in the middle","Only pedestrians are allowed to cross"],"correct":"Four roads meet at a single point, typically forming a crossroads"},{"id":"96f8e3ff","question":"What characterizes a \"staggered junction\"?","answers":["All roads meet at exactly the same point","Two T-junctions positioned close together but offset, so roads don''t align directly opposite each other","It has no traffic control at all","It only exists on highways"],"correct":"Two T-junctions positioned close together but offset, so roads don''t align directly opposite each other"}]'::jsonb),
('e129f667-0510-4f07-9847-edb58356dc74',10,'video:1ea82216','Beginner course','First Aid for Drivers','video','[]'::jsonb),
('e129f667-0510-4f07-9847-edb58356dc74',10,'quiz:4ed3d448','Beginner course','You drove into a quiz','quiz','[{"id":"0c45cca2","question":"In India, what is generally required before you can apply for a permanent driving licence?","answers":["Directly apply without any prior step","Hold a valid learner''s licence for a minimum mandated period","Only pass a written test with no practical test","Only be above 25 years of age"],"correct":"Hold a valid learner''s licence for a minimum mandated period"},{"id":"f32ac6fc","question":"Which of the following is a common classification used for road accidents?","answers":["Accidents are only classified by the color of vehicles involved","By severity — such as fatal, grievous injury, minor injury, and non-injury (property damage only)","By the time of year only","Accidents cannot be classified in any way"],"correct":"By severity — such as fatal, grievous injury, minor injury, and non-injury (property damage only)"},{"id":"1d811a98","question":"Which of these is one of the most commonly cited causes of road accidents?","answers":["Following traffic signals correctly","Driver error, such as speeding, distraction, or not maintaining a safe distance","Using indicators before turning","Wearing a seatbelt"],"correct":"Driver error, such as speeding, distraction, or not maintaining a safe distance"},{"id":"5d17cacb","question":"Which of the following is an effective preventive measure to reduce accident risk?","answers":["Driving as close as possible to the vehicle ahead to save time","Maintaining a safe following distance, obeying speed limits, and staying alert/undistracted","Using a mobile phone while driving to stay connected","Ignoring weather conditions while driving"],"correct":"Maintaining a safe following distance, obeying speed limits, and staying alert/undistracted"},{"id":"3b17fa26","question":"What is a driver legally and ethically expected to do immediately after being involved in an accident?","answers":["Leave the scene quickly to avoid delay","Stop, check for injuries, help if possible, and report the accident as required by law","Move the vehicle immediately regardless of injuries or evidence needs","Only act if there is visible vehicle damage"],"correct":"Stop, check for injuries, help if possible, and report the accident as required by law"}]'::jsonb),
