('f60e5fdb-787a-4b40-844d-4e66416a6c8f',1,'quiz:7aa3526f','Flyover','clueless about gears','quiz','[{"id":"5ddb4e5c","question":"What should you do before shifting gears in a manual car?","answers":["Press the clutch pedal fully","Press the brake pedal fully"],"correct":"Press the clutch pedal fully"},{"id":"d5674370","question":"Which gear should you use when driving uphill in a manual car?","answers":["First or second gear for more power and torque, essential for going uphill","Fifth gear for cruising at higher speeds."],"correct":"First or second gear for more power and torque, essential for going uphill"},{"id":"9ffb7efa","question":"Why is it important to maintain your lane while driving?","answers":["It prevents accidents by ensuring predictable movements","It saves fuel"],"correct":"It prevents accidents by ensuring predictable movements"},{"id":"f2a07031","question":"How often should you check your mirrors while driving?","answers":["Every 5-8 seconds","Only when changing lanes"],"correct":"Every 5-8 seconds"}]'::jsonb),
