('f60e5fdb-787a-4b40-844d-4e66416a6c8f',2,'quiz:9332391b','Flyover','flyover flow facts','quiz','[{"id":"00cc0820","question":"What''s key to driving safely on a flyover?","answers":["Maintaining steady speed and lane discipline","Driving faster to avoid traffic"],"correct":"Maintaining steady speed and lane discipline"},{"id":"16f9ac33","question":"What should you do when merging or exiting a flyover?","answers":["Adjust your speed to match traffic and signal in advance","Brake suddenly and exit quickly"],"correct":"Brake suddenly and exit quickly"},{"id":"3d024aab","question":"How can you signal to another driver that you are about to overtake them at night?","answers":["Flash your high beams briefly to communicate your intention","Honk your horn repeatedly"],"correct":"Flash your high beams briefly to communicate your intention"},{"id":"eddf0201","question":"What is the best practice for parking at night in a poorly lit area?","answers":["Use your hazard lights to increase visibility while parking","Park quickly without using additional lights"],"correct":"Use your hazard lights to increase visibility while parking"}]'::jsonb),
